import { Payload } from 'payload'
import type { PayloadJob } from '@/payload-types'

// Narrow type to the union of known task slugs generated by Payload
export type KnownTaskSlug = NonNullable<PayloadJob['taskSlug']>

/**
 * Idempotently schedules a job by:
 * 1) Deleting any untried (pending) jobs for the same taskSlug
 * 2) Enqueuing a fresh job with empty input into the specified queue
 */
export const safeScheduleTask = async (
  payload: Payload,
  task: KnownTaskSlug,
  queue: string,
  input: Record<string, any> = {},
): Promise<void> => {
  // 1) Delete only untried jobs of this specific task
  await payload.delete({
    collection: 'payload-jobs',
    where: {
      taskSlug: { in: [task] },
      totalTried: { equals: 0 },
    },
  })

  // 2) Queue a fresh job with empty input
  await payload.jobs.queue({
    task,
    queue,
    input,
  })
}
